import {
  BarChart,
  Callout,
  Card,
  CardBody,
  CardHeader,
  Code,
  Divider,
  Grid,
  H1,
  H2,
  H3,
  Pill,
  Row,
  Select,
  Spacer,
  Stack,
  Stat,
  Table,
  Text,
  Toggle,
  useCanvasState,
  useHostTheme,
} from "cursor/canvas";

type AnyRecord = Record<string, unknown>;

const preSmall = {
  margin: 0,
  whiteSpace: "pre-wrap" as const,
  fontFamily: "var(--font-mono, ui-monospace, monospace)",
  fontSize: 12,
  lineHeight: 1.45,
};

function asArray<T = AnyRecord>(value: unknown): T[] {
  return Array.isArray(value) ? (value as T[]) : [];
}

function asRecord(value: unknown): AnyRecord {
  return value && typeof value === "object" && !Array.isArray(value) ? (value as AnyRecord) : {};
}

function modeLabel(mode: string): string {
  if (mode === "prior_only") return "Prior only";
  if (mode === "prior_plus_support_content_only") return "Prior + support";
  if (mode === "prior_plus_support_content_plus_lexical_hints") return "Prior + support + retrieval terms";
  return mode;
}

function clipText(text: string, max = 2400): string {
  if (text.length <= max) return text;
  return `${text.slice(0, max)}\n… [${text.length - max} chars truncated]`;
}

function verdictPill(verdict: string) {
  if (verdict === "PASS" || verdict === "GREEN") return <Pill tone="success">{verdict}</Pill>;
  if (verdict === "EVALUATOR") return <Pill tone="neutral">{verdict}</Pill>;
  if (verdict === "REVIEW") return <Pill tone="warning">{verdict}</Pill>;
  return <Pill tone="danger">{verdict}</Pill>;
}

function surfacePill(surface: string) {
  if (surface === "ok_or_later_stage") return <Pill tone="success">{surface}</Pill>;
  if (surface === "evaluator_only_not_planner_facing") return <Pill tone="neutral">{surface}</Pill>;
  if (surface.includes("leak") || surface.includes("failure") || surface.includes("regression")) {
    return <Pill tone="danger">{surface}</Pill>;
  }
  return <Pill tone="warning">{surface}</Pill>;
}

function MetricStrip({ metrics }: { metrics: AnyRecord }) {
  const budget = asRecord(metrics.budget);
  const surfaces = asRecord(metrics.context_surfaces);
  const usability = asRecord(metrics.llm_usability);
  const lanes = asRecord(metrics.presentation_lanes);
  const laneShare = asRecord(lanes.lane_token_share);
  const topLane = Object.entries(laneShare)
    .sort((a, b) => Number(b[1]) - Number(a[1]))
    .slice(0, 2)
    .map(([k, v]) => `${k} ${(Number(v) * 100).toFixed(0)}%`)
    .join(" · ");

  return (
    <Grid columns={4} gap={8}>
      <Stat value={String(surfaces.admitted_context_count ?? 0)} label="Admitted items" />
      <Stat value={String(surfaces.retrieved_context_count ?? 0)} label="Retrieved items" />
      <Stat
        value={String(usability.score_1_to_5 ?? "—")}
        label="LLM usability (1–5)"
        tone={Number(usability.score_1_to_5) >= 4 ? "success" : Number(usability.score_1_to_5) <= 2 ? "warning" : "neutral"}
      />
      <Stat value={String(budget.rendered_estimated_tokens ?? 0)} label="Rendered est. tokens" />
      {topLane ? (
        <Text size="small" tone="secondary" style={{ gridColumn: "1 / -1" }}>
          Lane token share: {topLane}
        </Text>
      ) : null}
    </Grid>
  );
}

function RenderedContextPanel({ packet }: { packet: AnyRecord }) {
  const theme = useHostTheme();
  const sections = asArray<AnyRecord>(packet.sections);
  const [openSection, setOpenSection] = useCanvasState<string>("c1s4_open_section", "");

  if (!packet.schema) {
    return (
      <Callout tone="warning" title="No rendered packet">
        This row has no rendered_context_packet (evaluator-only or missing Step 2 packet).
      </Callout>
    );
  }

  return (
    <Stack gap={10}>
      <Row gap={8} wrap>
        <Pill tone="info">{String(packet.schema)}</Pill>
        <Text size="small" tone="secondary">
          {sections.length} sections · {String(packet.rendered_text ?? "").length} chars full text
        </Text>
      </Row>

      <Card collapsible defaultOpen>
        <CardHeader title="Full prompt text (what the planner would see)" />
        <CardBody>
          <pre style={{ ...preSmall, maxHeight: 320, overflow: "auto", color: theme.text.primary }}>
            {clipText(String(packet.rendered_text ?? ""), 4000) || "— (empty)"}
          </pre>
        </CardBody>
      </Card>

      <Stack gap={8}>
        <H3>Sections</H3>
        {sections.map((section) => {
          const id = String(section.section_id ?? section.title ?? "section");
          const isOpen = openSection === id;
          return (
            <Card
              key={id}
              collapsible
              open={isOpen}
              onOpenChange={(open) => setOpenSection(open ? id : "")}
            >
              <CardHeader
                title={String(section.title ?? section.section_id ?? "Section")}
                trailing={
                  <Row gap={6}>
                    <Pill tone="neutral">{asArray(section.refs).length} refs</Pill>
                    <Pill tone="neutral">{String(section.estimated_tokens ?? 0)} tok</Pill>
                  </Row>
                }
              />
              <CardBody>
                <pre style={{ ...preSmall, maxHeight: 280, overflow: "auto", color: theme.text.primary }}>
                  {clipText(String(section.text ?? ""), 2000) || "— (none)"}
                </pre>
              </CardBody>
            </Card>
          );
        })}
      </Stack>
    </Stack>
  );
}

function ModeGuidePanel({ guide }: { guide: AnyRecord }) {
  const modes = asArray<AnyRecord>(guide.modes);
  const legend = asArray<AnyRecord>(guide.verdict_legend);
  const contracts = asArray<string>(guide.contracts);

  return (
    <Card collapsible defaultOpen>
      <CardHeader title={String(guide.title || "How to read this canvas")} />
      <CardBody>
        <Stack gap={14}>
          <Text>{String(guide.scope ?? "")}</Text>
          {guide.decision ? (
            <Callout tone="info" title="Decision">
              {String(guide.decision)}
            </Callout>
          ) : null}

          <Stack gap={10}>
            <H3>Retrieval field policies</H3>
            {modes.map((mode) => (
              <Card key={String(mode.id)} collapsible>
                <CardHeader title={String(mode.label ?? mode.id)} />
                <CardBody>
                  <Stack gap={8}>
                    <Text size="small">{String(mode.summary ?? "")}</Text>
                    <Text size="small" tone="secondary">
                      Includes: {asArray<string>(mode.includes).join("; ") || "—"}
                    </Text>
                    <Text size="small" tone="secondary">
                      Excludes: {asArray<string>(mode.excludes).join("; ") || "—"}
                    </Text>
                    <Text size="small" tone="secondary">
                      Diagnostic: {String(mode.diagnostic_use ?? "")}
                    </Text>
                  </Stack>
                </CardBody>
              </Card>
            ))}
          </Stack>

          <Stack gap={8}>
            <H3>Verdict legend</H3>
            <Table
              headers={["Verdict", "Meaning"]}
              rows={legend.map((row) => [String(row.verdict ?? ""), String(row.meaning ?? "")])}
            />
          </Stack>

          {contracts.length ? (
            <Stack gap={6}>
              <Text size="small" tone="secondary">
                Contracts
              </Text>
              {contracts.map((path) => (
                <Code key={path}>{path}</Code>
              ))}
            </Stack>
          ) : null}
        </Stack>
      </CardBody>
    </Card>
  );
}

function rankText(value: unknown): string {
  if (value === null || value === undefined || value === "") return "miss";
  return String(value);
}

function SupportFieldPolicyPanel({ policy }: { policy: AnyRecord }) {
  const rows = asArray<AnyRecord>(policy.rows);
  const counts = asRecord(policy.counts);

  if (!rows.length) return null;

  return (
    <Stack gap={10}>
      <H2>Support Retrieval Field Policy</H2>
      <Callout tone="info" title="Demo lane decision">
        {String(policy.decision_note ?? "")}
      </Callout>
      <Text size="small" tone="secondary">
        {String(policy.metric_note ?? "")}
      </Text>
      <Grid columns={4} gap={8}>
        <Stat value={String(counts.support_required_questions ?? rows.length)} label="Support-required questions" />
        <Stat value={String(counts.candidate_lift_from_retrieval_terms ?? 0)} label="Candidate hit lift" />
        <Stat value={String(counts.candidate_rank_improvements ?? 0)} label="Candidate rank improves" />
        <Stat value={String(counts.support_token_share_increases ?? 0)} label="Token-share increases" />
      </Grid>
      <Table
        headers={[
          "Q#",
          "Content candidate",
          "Terms candidate",
          "Content admitted",
          "Terms admitted",
          "Token share delta",
          "Terms surface",
        ]}
        rows={rows.map((row) => [
          `Q${String(row.question_number ?? "")}`,
          rankText(row.content_only_candidate_rank),
          rankText(row.retrieval_terms_candidate_rank),
          rankText(row.content_only_admitted_rank),
          rankText(row.retrieval_terms_admitted_rank),
          String(row.support_token_share_delta ?? ""),
          String(row.retrieval_terms_surface ?? ""),
        ])}
      />
    </Stack>
  );
}

function QuestionReviewCard({ card }: { card: AnyRecord }) {
  const verdict = String(card.verdict ?? "");
  const missing = asArray<string>(card.missing_required_groups);
  const matched = asArray(card.required_context_groups);
  const packet = asRecord(card.rendered_context_packet);
  const metrics = asRecord(card.packet_quality_metrics);
  const admitted = asArray<AnyRecord>(card.admitted_context_preview);
  const gaps = asArray(card.source_derived_context_gaps);
  const violations = asArray<string>(card.violations);
  const gradingTier = String(card.grading_tier ?? "");
  const isEvaluator = verdict === "EVALUATOR" || card.planner_facing === false;

  return (
    <Card collapsible defaultOpen={Boolean(card.open_by_default)}>
      <CardHeader
        title={`Q${String(card.question_number ?? "?")} · ${modeLabel(String(card.mode ?? ""))}`}
        trailing={
          <Row gap={8} align="center">
            {card.required_groups_label ? <Pill tone="neutral">{String(card.required_groups_label)}</Pill> : null}
            {surfacePill(String(card.next_failure_surface ?? ""))}
            {verdictPill(verdict)}
          </Row>
        }
      />
      <CardBody>
        <Stack gap={12}>
          <Row gap={8} wrap>
            <Pill tone="neutral">{String(card.question_id ?? "")}</Pill>
            {card.beat_id ? <Pill tone="neutral">{String(card.beat_id)}</Pill> : null}
            <Pill tone="neutral">{String(card.authority_label ?? "")}</Pill>
            <Pill tone="neutral">{gradingTier}</Pill>
          </Row>

          {card.question ? <Text weight="medium">{String(card.question)}</Text> : null}

          {card.expected_mode_behavior ? (
            <Text size="small" tone="secondary">
              Expected: {String(card.expected_mode_behavior)}
            </Text>
          ) : null}

          {isEvaluator ? (
            <Callout tone="neutral" title="Evaluator-only">
              This question is not planner-facing in this retrieval mode. No rendered planner context is expected.
            </Callout>
          ) : null}

          {!isEvaluator && violations.length ? (
            <Callout tone="danger" title="Violations">
              <Row gap={6} wrap>
                {violations.map((v) => (
                  <Pill key={v} tone="danger">
                    {v}
                  </Pill>
                ))}
              </Row>
            </Callout>
          ) : null}

          {!isEvaluator && gradingTier === "strict_gold" ? (
            missing.length ? (
              <Callout tone="danger" title="Missing required groups (strict gold)">
                <Row gap={6} wrap>
                  {missing.map((g) => (
                    <Pill key={g} tone="danger">
                      {g}
                    </Pill>
                  ))}
                </Row>
              </Callout>
            ) : (
              <Callout tone="success" title="Strict gold required groups">
                All required groups satisfied for this mode.
              </Callout>
            )
          ) : null}

          {!isEvaluator ? (
            <Row gap={8} wrap>
              <Pill tone="neutral">{String(card.retrieval_sufficiency_class ?? "")}</Pill>
              <Pill tone="neutral">{String(card.support_policy_status ?? "")}</Pill>
              {card.support_required ? <Pill tone="info">support_required</Pill> : null}
              {card.first_support_candidate_rank ? (
                <Pill tone="neutral">candidate rank {String(card.first_support_candidate_rank)}</Pill>
              ) : null}
              {card.first_support_admitted_rank ? (
                <Pill tone="neutral">admitted rank {String(card.first_support_admitted_rank)}</Pill>
              ) : null}
              {card.known_context_gaps_leaked ? <Pill tone="danger">gap_leak</Pill> : null}
              {card.generated_answer_control_leak ? <Pill tone="danger">answer_control_leak</Pill> : null}
            </Row>
          ) : null}

          {!isEvaluator && matched.length ? (
            <Stack gap={6}>
              <Text size="small" tone="secondary">
                Matched groups ({matched.length})
              </Text>
              <Row gap={6} wrap>
                {matched.map((g, i) => {
                  const rec = asRecord(g);
                  const id = String(rec.group_id ?? rec.id ?? i);
                  return (
                    <Pill key={id} tone="success">
                      {id}
                    </Pill>
                  );
                })}
              </Row>
            </Stack>
          ) : null}

          {!isEvaluator && admitted.length ? (
            <Card collapsible>
              <CardHeader title={`Admitted context preview (${card.admitted_context_count ?? admitted.length})`} />
              <CardBody>
                <Table
                  headers={["Ref", "Kind", "Lane", "Title"]}
                  rows={admitted.map((item) => [
                    String(item.ref ?? ""),
                    String(item.source_kind ?? ""),
                    String(item.presentation_lane ?? ""),
                    String(item.title ?? ""),
                  ])}
                />
              </CardBody>
            </Card>
          ) : null}

          {!isEvaluator && gaps.length ? (
            <Card collapsible>
              <CardHeader title={`Source-derived gaps (${card.source_derived_gap_count ?? gaps.length})`} />
              <CardBody>
                <pre style={preSmall}>{clipText(JSON.stringify(gaps, null, 2), 1500)}</pre>
              </CardBody>
            </Card>
          ) : null}

          {!isEvaluator && Object.keys(metrics).length ? <MetricStrip metrics={metrics} /> : null}

          {!isEvaluator ? (
            <Card collapsible defaultOpen={verdict !== "GREEN" && verdict !== "PASS"}>
              <CardHeader title="Rendered LLM context" />
              <CardBody>
                <RenderedContextPanel packet={packet} />
              </CardBody>
            </Card>
          ) : null}
        </Stack>
      </CardBody>
    </Card>
  );
}

export default function C1S4ExpectedContextBenchmarkCanvas() {
  const data = c1s4ExpectedContextCanvasData as AnyRecord;
  const summary = asRecord(data.summary);
  const statTiles = asArray<AnyRecord>(summary.statTiles);
  const modeRows = asArray<AnyRecord>(data.modeRows);
  const questionCards = asArray<AnyRecord>(data.questionCards);
  const modeGuide = asRecord(data.modeGuide);
  const supportFieldPolicy = asRecord(data.supportFieldPolicy);
  const sources = asRecord(data.sources);
  const surfaceSummary = asRecord(summary.surfaceSummary);
  const failureCounts = asRecord(surfaceSummary.failure_surface_counts);
  const modeOptions = asArray<{ value: string; label: string }>(summary.modeOptions);

  const [filterMode, setFilterMode] = useCanvasState("c1s4_filter_mode", "all");
  const [onlyNonGreen, setOnlyNonGreen] = useCanvasState("c1s4_only_non_green", false);
  const [questionFilter, setQuestionFilter] = useCanvasState("c1s4_question_filter", "all");

  const questionOptions = [
    { value: "all", label: "All questions" },
    ...Array.from(new Set(questionCards.map((c) => String(c.question_number ?? ""))))
      .filter(Boolean)
      .sort((a, b) => Number(a) - Number(b))
      .map((qn) => ({ value: qn, label: `Q${qn}` })),
  ];

  const filteredCards = questionCards.filter((card) => {
    if (filterMode !== "all" && String(card.mode) !== filterMode) return false;
    if (questionFilter !== "all" && String(card.question_number) !== questionFilter) return false;
    if (onlyNonGreen) {
      const surface = String(card.next_failure_surface ?? "");
      const verdict = String(card.verdict ?? "");
      if (surface === "ok_or_later_stage" && (verdict === "GREEN" || verdict === "PASS")) return false;
    }
    return true;
  });

  const greenCount = questionCards.filter(
    (c) => String(c.next_failure_surface) === "ok_or_later_stage" || c.verdict === "PASS" || c.verdict === "GREEN",
  ).length;

  const chartCategories = modeRows.map((r) => modeLabel(String(r.mode ?? "")));
  const greenValues = modeRows.map((r) => Number(r.surface_green ?? 0));
  const reviewValues = modeRows.map((r) => Number(r.surface_non_green ?? 0));

  return (
    <Stack gap={20} style={{ padding: 16, maxWidth: 1100, margin: "0 auto" }}>
      <Stack gap={8}>
        <Text tone="secondary" size="small">
          DungeonMindBuddy · C1S4 preplanning context benchmark
        </Text>
        <H1>{String(data.title ?? "C1S4 Planner Context Review")}</H1>
        <Text tone="secondary">{String(data.subtitle ?? "")}</Text>
        <Row gap={12} wrap>
          {sources.report ? <Code>{String(sources.report)}</Code> : null}
          {sources.targets ? <Code>{String(sources.targets)}</Code> : null}
          {sources.gold ? <Code>{String(sources.gold)}</Code> : null}
        </Row>
      </Stack>

      {Object.keys(modeGuide).length ? <ModeGuidePanel guide={modeGuide} /> : null}

      <Grid columns={3} gap={12}>
        {statTiles.slice(0, 6).map((tile, idx) => (
          <Stat
            key={`${String(tile.label)}-${idx}`}
            value={String(tile.value ?? "")}
            label={String(tile.label ?? "")}
            tone={
              String(tile.label ?? "").includes("Hard boundary") && Number(tile.value) > 0
                ? "danger"
                : String(tile.label ?? "").includes("green") || String(tile.label ?? "").includes("Tier A")
                  ? "success"
                  : String(tile.label ?? "").includes("review") && Number(tile.value) > 0
                    ? "warning"
                    : "neutral"
            }
          />
        ))}
      </Grid>

      {Object.keys(failureCounts).length ? (
        <Card>
          <CardHeader title="Failure surface distribution (all planner rows)" />
          <CardBody>
            <Table
              headers={["Surface", "Count"]}
              rows={Object.entries(failureCounts)
                .sort((a, b) => Number(b[1]) - Number(a[1]))
                .map(([surface, count]) => [surface, String(count)])}
            />
          </CardBody>
        </Card>
      ) : null}

      {modeRows.length ? (
        <Stack gap={10}>
          <H2>Mode comparison</H2>
          <Text size="small" tone="secondary">
            Demo policy is content + retrieval_terms. Content-only and prior-only remain ablations/controls.
            Green = ok_or_later_stage heuristic · Strict gold = Q1/Q3/Q5 only.
          </Text>
          <BarChart
            categories={chartCategories}
            series={[
              { name: "Surface green", data: greenValues, tone: "success" },
              { name: "Needs review", data: reviewValues, tone: "warning" },
            ]}
            horizontal
            height={Math.max(140, chartCategories.length * 56)}
          />
          <Table
            headers={["Mode", "Planner rows", "Green", "Review", "Support missing", "Strict gold OK", "Strict fail"]}
            rows={modeRows.map((row) => [
              modeLabel(String(row.mode ?? "")),
              String(row.planner_rows ?? ""),
              String(row.surface_green ?? ""),
              String(row.surface_non_green ?? ""),
              String(row.support_expected_missing ?? ""),
              String(row.strict_gold_ok ?? row.rows_ok ?? ""),
              String(row.strict_gold_failed ?? row.rows_failed ?? ""),
            ])}
          />
        </Stack>
      ) : null}

      {Object.keys(supportFieldPolicy).length ? (
        <>
          <Divider />
          <SupportFieldPolicyPanel policy={supportFieldPolicy} />
        </>
      ) : null}

      <Divider />

      <Stack gap={12}>
        <H2>Questions — full deep dive</H2>
        <Text size="small" tone="secondary">
          Every benchmark question at every retrieval mode. Expand any card for admitted context, gaps, metrics, and
          the rendered LLM prompt text.
        </Text>

        <Card>
          <CardHeader title="Filters" />
          <CardBody>
            <Row gap={16} align="center" wrap>
              <Select
                value={filterMode}
                onChange={setFilterMode}
                options={modeOptions.length ? modeOptions : [{ value: "all", label: "All modes" }]}
              />
              <Select value={questionFilter} onChange={setQuestionFilter} options={questionOptions} />
              <Row gap={8} align="center">
                <Toggle checked={onlyNonGreen} onChange={setOnlyNonGreen} />
                <Text size="small">Only non-green / needs review</Text>
              </Row>
              <Spacer />
              <Text size="small" tone="secondary">
                Showing {filteredCards.length} of {questionCards.length} cards ({greenCount} green-ish)
              </Text>
            </Row>
          </CardBody>
        </Card>

        {filteredCards.length ? (
          filteredCards.map((card, idx) => (
            <QuestionReviewCard key={`${String(card.mode)}-${String(card.question_id)}-${idx}`} card={card} />
          ))
        ) : (
          <Callout tone="neutral" title="No cards match filters">
            Widen filters or turn off &quot;Only non-green&quot;.
          </Callout>
        )}
      </Stack>
    </Stack>
  );
}
